CREATE TABLE ezdfsfile (name_hash VARCHAR(34) DEFAULT '' NOT NULL, name CLOB NOT NULL, name_trunk CLOB NOT NULL, datatype VARCHAR(255) DEFAULT 'application/octet-stream' NOT NULL, scope VARCHAR(25) DEFAULT '' NOT NULL, size BIGINT UNSIGNED DEFAULT 0 NOT NULL, mtime INTEGER DEFAULT 0 NOT NULL, expired BOOLEAN DEFAULT '0' NOT NULL, status BOOLEAN DEFAULT '0' NOT NULL, PRIMARY KEY(name_hash));
